import{_ as a}from"./chunks/rmlui.IQCB0h4b.js";import{_ as t,o as r,c as i,a2 as s}from"./chunks/framework.Ky-Ipuyb.js";const g=JSON.parse('{"title":"RmlUi guide","description":"","frontmatter":{"lang":"en","sourcePath":"docs/rmlui/README.md"},"headers":[],"relativePath":"rmlui/index.md","filePath":"rmlui/index.md"}'),n={name:"rmlui/index.md"};function d(o,e,l,h,c,m){return r(),i("div",null,[...e[0]||(e[0]=[s('<h1 id="rmlui-guide" tabindex="-1">RmlUi guide <a class="header-anchor" href="#rmlui-guide" aria-label="Permalink to &quot;RmlUi guide&quot;">​</a></h1><p><a class="library-brand" href="https://mikke89.github.io/RmlUiDoc/"><img src="'+a+`" width="246" height="84" alt="RmlUi"></a></p><p>Build a document-based interface inside an SFML window with <code>sfml.js-rmlui</code>. RML describes the element tree, RCSS controls its presentation, and JavaScript owns application state and event handlers. The current sources target RmlUi 6.3 and SFML 3.1.</p><p>Start with JavaScript and the <a href="/guide/window">SFML window guide</a>. RmlUi 6.3 resembles HTML/CSS but does not embed a browser. <a href="/rmlui/data-models">Native data models</a> cover scalar and callback bindings, recursive records and arrays, custom variables, shared numeric storage and sparse updates. The guides below cover the runtime, document tree, styles, rendering, input, fonts, scripts and resource ownership; the <a href="/reference/rmlui/" target="_self">API reference</a> documents their TypeScript contracts.</p><h2 id="what-is-rmlui" tabindex="-1">What is RmlUi? <a class="header-anchor" href="#what-is-rmlui" aria-label="Permalink to &quot;What is RmlUi?&quot;">​</a></h2><p><a href="https://github.com/mikke89/RmlUi" target="_blank" rel="noreferrer">RmlUi</a> is a C++ UI library with HTML/CSS-inspired document authoring. Load an RML document once to create a persistent element tree, style it with RCSS, then update individual elements when application state changes. RmlUi handles layout and generates geometry; this package renders it through SFML.</p><p>It suits game menus, HUDs, inventory windows and interfaces whose layout and visual design belong in separate assets. RML, RCSS and the Node.js event handlers work together without a browser DOM or web JavaScript environment. For tools composed from widget calls every frame, see the <a href="/imgui/">ImGui guide</a>.</p><p><a href="https://mikke89.github.io/RmlUiDoc/" target="_blank" rel="noreferrer">Official documentation</a> · <a href="https://github.com/mikke89/RmlUi" target="_blank" rel="noreferrer">Official repository</a></p><h2 id="learning-path" tabindex="-1">Learning path <a class="header-anchor" href="#learning-path" aria-label="Permalink to &quot;Learning path&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Chapter</th><th>What it covers</th></tr></thead><tbody><tr><td><a href="/rmlui/getting-started">Quick start</a></td><td>Run the counter and understand initialization, fonts and frame order</td></tr><tr><td><a href="/rmlui/rml-rcss">RML and RCSS basics</a></td><td>Write markup, selectors and layout, connect clicks, and find official syntax references</td></tr><tr><td><a href="/rmlui/documents">Documents and events</a></td><td>Load RML, edit elements, register listeners and release native objects</td></tr><tr><td><a href="/rmlui/debugger">Native Debugger</a></td><td>Inspect elements, logs and reflected data models in a separate host</td></tr><tr><td><a href="/rmlui/vector-elements">SVG and Lottie</a></td><td>Native vector elements, decorators, animation frames and sources</td></tr><tr><td><a href="/rmlui/geometry-utilities">Native geometry and convolution</a></td><td>Generate meshes in Native batches and filter shared alpha buffers</td></tr><tr><td><a href="/rmlui/rendering">Rendering and Retina</a></td><td>Compose SFML and RmlUi, size high-density interfaces and assess effects</td></tr><tr><td><a href="/rmlui/performance">Shared storage and batching</a></td><td>Submit numeric commands, batch custom calculations and preload resources</td></tr><tr><td><a href="/rmlui/api">API guide</a></td><td>Find types, defaults, return values and lifetime contracts</td></tr></tbody></table><p>These guides and the source-generated API reference are maintained in English, Simplified Chinese, Japanese and Korean.</p><h2 id="run-an-example" tabindex="-1">Run an example <a class="header-anchor" href="#run-an-example" aria-label="Permalink to &quot;Run an example&quot;">​</a></h2><p>From the monorepo root:</p><div class="language-sh vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">sh</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">node</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> tools/bootstrap.cjs</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">node</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> packages/sfml.js-rmlui/examples/demo.cjs</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">node</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> packages/sfml.js-rmlui/examples/official.cjs</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> variables</span></span></code></pre></div><p>The <a href="/examples/rmlui">examples catalogue</a> includes screenshots, controls and source links. The counter has a working Increment button. The variables page&#39;s mission buttons demonstrate hover styling only.</p><h2 id="ownership-boundary" tabindex="-1">Ownership boundary <a class="header-anchor" href="#ownership-boundary" aria-label="Permalink to &quot;Ownership boundary&quot;">​</a></h2><p>The process-wide runtime binds one <code>RenderWindow</code> and belongs to its initializing Node.js environment and thread. It owns contexts, documents, fonts and renderer resources. Element wrappers share native validity. JS references retain owned detached trees; attached nodes follow their native parent&#39;s lifetime. Destruction automatically releases listeners, and stale wrapper access throws. Shut down RmlUi before closing the SFML window. See <a href="/rmlui/documents#native-lifetimes">native lifetimes</a> for deferred document destruction and worker restrictions.</p>`,17)])])}const f=t(n,[["render",d]]);export{g as __pageData,f as default};
